import { useState, type FormEvent as ReactFormEvent } from "react";
import { AuthBrandPanel } from "@/components/branding/AuthBrandPanel";
import { UsersIcon } from "@/components/icons";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { useAuth } from "@/contexts/AuthContext";
import { useCurrentVersion } from "@/features/changelog";
import { useNavigateTransition } from "@/hooks/useNavigateTransition";
import { useLocation } from "@/lib/router-compat";
import {
  dismissAuthError,
  notifyAuthError,
  notifySuccess,
} from "@/lib/ui/appFeedback";
import { AuthForm, type AuthMode } from "../components/AuthForm";
import { useRecoveryStatus } from "../hooks/useRecoveryStatus";
import { endRecovery, getRecoveryUserId } from "../recoverySession";
import { AuthCardHeader, AuthModeLinks, RecoveryNotice } from "./AuthPageParts";

export default function AuthPage() {
  const { user, signIn, signOut, resetPassword, updatePassword } = useAuth();
  const { pathname } = useLocation();
  const navigate = useNavigateTransition();
  const recovery = useRecoveryStatus();


  const unknownPath =
    recovery === "idle" &&
    pathname !== "/" &&
    pathname !== "/login" &&
    pathname !== "/auth";
  const [mode, setMode] = useState<AuthMode>(
    recovery === "idle" ? "sign-in" : "reset",
  );
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const currentVersion = useCurrentVersion();


  function leaveAuthRoute() {
    if (pathname === "/auth") navigate("/");
  }



  const [prevRecovery, setPrevRecovery] = useState(recovery);
  if (prevRecovery !== recovery) {
    setPrevRecovery(recovery);
    setMode(recovery === "idle" ? "sign-in" : "reset");
  }


  const finishRecovery = (nextMode: AuthMode) => {
    endRecovery();
    setPrevRecovery("idle");
    setMode(nextMode);
  };






  const recoverySessionMatches =
    recovery === "active" && !!user && user.id === getRecoveryUserId();
  const canSubmitReset = recoverySessionMatches;

  const cancelRecovery = async () => {
    setPassword("");


    if (recoverySessionMatches) await signOut();
    finishRecovery("sign-in");
  };

  const runSubmit = async () => {


    dismissAuthError();
    if (mode === "forgot") {
      const { error } = await resetPassword(email);
      if (error) notifyAuthError({ error });
      else notifySuccess("Revisa tu correo para restablecer tu contraseña");
      return;
    }
    if (mode === "reset") {
      if (!canSubmitReset) return;
      const { error } = await updatePassword(password);
      if (error) {
        notifyAuthError({ error });
        return;
      }
      notifySuccess("Contraseña actualizada");
      setPassword("");
      finishRecovery("sign-in");


      leaveAuthRoute();
      return;
    }
    const { error } = await signIn(email, password);
    if (error) notifyAuthError({ error });
    else {
      dismissAuthError();
      leaveAuthRoute();
    }
  };

  const handleSubmit = async (e: ReactFormEvent) => {
    e.preventDefault();
    setLoading(true);
    await runSubmit();
    setLoading(false);
  };

  return (
    <main className="auth-brandscape min-h-[100dvh] flex bg-background">
      <AuthBrandPanel tagline="Levanta el futuro de tu operación." />
      <div className="flex-1 flex items-center justify-center bg-background p-4">
        <Card className="w-full max-w-md animate-fade-in shadow-lg">
          <AuthCardHeader
            mode={mode}
            unknownPath={unknownPath}
            pathname={pathname}
          />
          <CardContent>
            {recovery === "error" || recovery === "pending" ? (
              <RecoveryNotice
                status={recovery}
                onRequestNew={() => {
                  finishRecovery("forgot");
                }}
              />
            ) : (
              <AuthForm
                mode={mode}
                email={email}
                password={password}
                showPassword={showPassword}
                loading={loading}
                onEmailChange={setEmail}
                onPasswordChange={setPassword}
                onToggleShowPassword={() => setShowPassword((v) => !v)}
                onSubmit={handleSubmit}
              />
            )}
            <AuthModeLinks
              mode={mode}
              recovery={recovery}
              onMode={setMode}
              onCancelRecovery={() => {
                void cancelRecovery();
              }}
            />

            <div className="relative my-4">
              <div className="absolute inset-0 flex items-center">
                <span className="w-full border-t" />
              </div>
              <div className="relative flex justify-center text-xs uppercase">
                <span className="bg-card px-2 text-muted-foreground">o</span>
              </div>
            </div>
            <Button
              variant="outline"
              className="w-full touch:min-h-11"
              onClick={() => navigate("/portal/login")}
            >
              <UsersIcon className="mr-2 h-4 w-4" /> Portal de Clientes
            </Button>
            {currentVersion && (
              <p className="mt-4 text-center text-3xs text-muted-foreground/60 font-mono">
                v{currentVersion}
              </p>
            )}
          </CardContent>
        </Card>
      </div>
    </main>
  );
}
